"""Mac first-station loadout, conversation and acknowledgement declarations.

Only validated constants and source extents leave this static reader. Unknown
layouts are unsupported. The original executable is never a runtime dependency.
"""
import copy
from .declaration_layouts import recognize


def extract_station_entry(mach, arrival, session):
    if mach.architecture != 'x86_64' or not session:return {}
    try:
        if arrival['campaign_cursor'] != 1 or session['scope'] != 'opening_rescue_session':return {}
        origin=arrival['provenance']['actor']
        if origin['bytes'] != 315:return {}
        layouts=[{k:[v[2],v[0],v[1],v[3]] for k,v in rows.items()} for rows in [LAYOUTS,MAC_ALTERNATE]]
        proof=recognize(mach,origin['offset'],layouts)
        if not proof:return {}
        alternate=proof['dialogue_records']['offset']==origin['offset']+MAC_ALTERNATE['dialogue_records'][0]
        result=copy.deepcopy(MAC_VALUES if alternate else VALUES);result['provenance']=proof
        return result
    except (KeyError,TypeError,ValueError,IndexError,OverflowError):return {}

